fn gcd_calc(m: u32, n: u32) -> u32 {
    debug_assert!(m > 0 && n > 0);

    let mut a = m;
    let mut b = n;

    // Euclid's algorithm:
    // - a and b stay > 0 (because we stop when b == 0, and the result is a > 0)
    // - gcd(a, b) is invariant under (a, b) -> (b, a % b)
    // - termination: when b > 0, a % b < b, so b strictly decreases
    while b != 0 {
        let r = a % b;
        a = b;
        b = r;
    }

    a
}